// Bundles the summary logic and the PDF maker into one plain JavaScript file the email function can import.
// Run: node scripts/build-report-bundle.mjs
import { build } from 'esbuild';

await build({
  entryPoints: ['src/logic/reportBundle.ts'],
  outfile: 'supabase/functions/send-reports/report.js',
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  mainFields: ['module', 'main'],
  target: 'es2022',
  minify: true,
  legalComments: 'inline',
  banner: { js: '// Generated by scripts/build-report-bundle.mjs from src/logic. Do not edit.\n// @ts-nocheck' },
});
console.log('Wrote supabase/functions/send-reports/report.js');
